import { retry } from "../src/lib/retry.ts";
import { EmailProviderError } from "../src/lib/email-client.ts";

let calls = 0;
async function flakySend() {
  calls++;
  if (calls < 4) throw new EmailProviderError(503, null);
  return { id: "msg_7f3a" };
}

// Retry overload and outages, plus timeouts and network errors (fetch throws a TypeError).
const retryable = (err: unknown) =>
  err instanceof EmailProviderError
    ? [429, 502, 503, 504].includes(err.status)
    : err instanceof Error && (err.name === "TimeoutError" || err.name === "TypeError");

const result = await retry(flakySend, {
  attempts: 5,
  baseMs: 200,
  maxMs: 5_000,
  retryable,
  onRetry: (err, attempt, waitMs) => console.log(`attempt ${attempt} failed (${(err as Error).message}), waiting ${waitMs} ms`),
});
console.log(`attempt ${calls} worked:`, result);

import CircuitBreaker from "opossum";
import { setTimeout as sleep } from "node:timers/promises";

let redisUp = false;
async function cacheGet(key: string): Promise<string | null> {
  console.log("  asking Redis");
  if (!redisUp) throw new Error("connect ECONNREFUSED 127.0.0.1:6379");
  return `cached ${key}`;
}

const breaker = new CircuitBreaker(cacheGet, {
  timeout: 500,
  errorThresholdPercentage: 50,
  volumeThreshold: 5,
  resetTimeout: 1_000,
});
breaker.fallback(() => null);
breaker.on("open", () => console.log("-> open: skipping Redis"));
breaker.on("halfOpen", () => console.log("-> half-open: trying Redis again"));
breaker.on("close", () => console.log("-> closed: using Redis"));

for (let i = 1; i <= 7; i++) {
  const value = await breaker.fire("roombook:availability:1:2026-10-05");
  console.log(`request ${i}: ${value ?? "miss, ask PostgreSQL"}`);
}
redisUp = true;
await sleep(1_100);
console.log(`request 8: ${await breaker.fire("roombook:availability:1:2026-10-05")}`);
breaker.shutdown();

