import { createHash } from "node:crypto";
import { UnprocessableError } from "../../domain/errors.ts";
import type { NewBooking } from "./bookings.model.ts";
import type { InTransaction } from "./deps.ts";
import { toBookingView } from "./bookings.view.ts";

export type Result = { status: number; body: unknown; replayed: boolean };

export async function createOnce(deps: { inTransaction: InTransaction }, key: string, input: NewBooking): Promise<Result> {
  const requestHash = createHash("sha256").update(JSON.stringify(input)).digest("hex");

  return deps.inTransaction(async ({ bookings, idempotency }) => {
    if (!(await idempotency.claim(input.userId, key, requestHash))) {
      const saved = await idempotency.find(input.userId, key);
      if (saved.requestHash !== requestHash) {
        throw new UnprocessableError("idempotency-key-reused", "This Idempotency-Key was used with a different request.");
      }
      return { status: saved.statusCode, body: saved.responseBody, replayed: true };
    }

    const body = toBookingView(await bookings.insert(input));
    await idempotency.complete(input.userId, key, 201, body);
    return { status: 201, body, replayed: false };
  });
}

import { Router } from "express";
import type pg from "pg";

export type Lifecycle = { draining: boolean };

export function healthRoutes(pool: pg.Pool, lifecycle: Lifecycle) {
  const router = Router();

  // Liveness: the process is up and its event loop answers. Nothing else.
  router.get("/healthz", (_req, res) => {
    res.set("Cache-Control", "no-store").json({ status: "ok" });
  });

  // Readiness: send me traffic. False while draining, or without PostgreSQL.
  router.get("/readyz", async (_req, res) => {
    res.set("Cache-Control", "no-store");
    if (lifecycle.draining) {
      res.status(503).json({ status: "draining" });
      return;
    }
    try {
      await pool.query("SELECT 1");
      res.json({ status: "ready" });
    } catch {
      res.status(503).json({ status: "unavailable", failing: ["postgres"] });
    }
  });

  return router;
}

