import type { Server } from "node:http";
import { setTimeout as sleep } from "node:timers/promises";
import type { Lifecycle } from "./http/health.ts";

type Closer = () => Promise<unknown>;

export function gracefulShutdown(server: Server, lifecycle: Lifecycle, closers: Closer[], drainMs = 5_000, graceMs = 20_000) {
  process.once("SIGTERM", async () => {
    console.log("SIGTERM: failing readiness, draining");
    lifecycle.draining = true;
    await sleep(drainMs); // let the load balancer notice the 503s

    console.log("closing the server: no new connections");
    const force = setTimeout(() => server.closeAllConnections(), graceMs);
    await new Promise((resolve) => server.close(resolve));
    clearTimeout(force);

    console.log("in-flight requests done, closing pools");
    await Promise.allSettled(closers.map((close) => close()));
    console.log("bye");
    process.exit(0);
  });
}

