import type pg from "pg";
import { setTimeout as sleep } from "node:timers/promises";
import type { Redis } from "../db/redis.ts";
import { withTransaction } from "../db/transaction.ts";

type OutboxRow = { id: number; event_type: string; payload: unknown };

// Moves committed events from the outbox table to the roombook:events stream.
export async function runOutboxRelay(pool: pg.Pool, redis: Redis, signal: AbortSignal) {
  while (!signal.aborted) {
    const moved = await withTransaction(pool, async (tx) => {
      const { rows } = await tx.query<OutboxRow>(
        `SELECT id, event_type, payload FROM outbox
         WHERE published_at IS NULL
         ORDER BY id LIMIT 100
         FOR UPDATE SKIP LOCKED`,
      );
      for (const row of rows) {
        await redis.xAdd("roombook:events", "*", {
          eventId: `evt_${row.id}`,
          type: row.event_type,
          payload: JSON.stringify(row.payload),
        });
      }
      if (rows.length > 0) {
        await tx.query("UPDATE outbox SET published_at = now() WHERE id = ANY($1)", [rows.map((r) => r.id)]);
      }
      return rows.length;
    });
    if (moved === 0) await sleep(1_000, undefined, { signal }).catch(() => {});
  }
}

