import express, { Router } from "express";
import type pg from "pg";
import { withTransaction } from "../db/transaction.ts";
import { verify } from "../lib/webhook-signature.ts";

type EmailEvent = { id: string; type: string; data: { to: string } };

export function emailEventsRouter(pool: pg.Pool, secret: string) {
  const router = Router();

  // express.raw keeps the exact bytes, which is what the signature covers.
  router.post("/v1/hooks/email", express.raw({ type: "application/json", limit: "100kb" }), async (req, res) => {
    const raw = (req.body as Buffer).toString("utf8");
    if (!verify(secret, req.get("Roombook-Signature") ?? "", raw)) {
      res.status(401).type("application/problem+json").json({
        type: "https://roombook.example/problems/bad-signature",
        title: "Signature check failed",
        status: 401,
      });
      return;
    }
    const event = JSON.parse(raw) as EmailEvent;

    await withTransaction(pool, async (tx) => {
      const { rowCount } = await tx.query(
        "INSERT INTO processed_events (event_id) VALUES ($1) ON CONFLICT DO NOTHING",
        [event.id],
      );
      if (rowCount === 1 && event.type === "email.bounced") {
        await tx.query("UPDATE users SET email_bounced_at = now() WHERE lower(email) = lower($1)", [event.data.to]);
      }
    });
    res.sendStatus(204);
  });

  return router;
}
